FUNCTION_BLOCK FB_OTEC_SeawaterHydraulicCondenser
(*
====================================================================================================
  LUMINA CYBER-PHYSICAL AUTOMATION ENGINE - ADVANCED PROCESS CONTROL CORE
  SYSTEM ARCHITECTURE : IEC 61131-3 / IEC 61508 SIL-2/SIL-3 COMPLIANT
  DOMAIN             : OCEAN THERMAL ENERGY CONVERSION (OTEC) CLOSED RANKINE CYCLE
  SUBSYSTEM          : WARM/COLD SEAWATER HYDRAULIC BALANCE & WORKING FLUID CONDENSER SUB-COOLING
  AUTHOR             : Principal Automation Fellow & Cyber-Physical Systems Chair
  DESIGN PHILOSOPHY  : Model-Predictive State-Space Decoupling, Triple Modular Redundant (2oo3)
                       Sensor Qualification, Deep-Riser Water Hammer Avoidance, Cavitation Suppr.
====================================================================================================
*)

VAR_INPUT
    (* Supervisory Commands & Operational Modes *)
    bEnable                     : BOOL;     (* Executive supervisory plant enable permissive [BOOL] *)
    bEmergencyStop              : BOOL;     (* Fail-safe de-energize to trip command (SIL-3 contact) [BOOL] *)
    bResetFaults                : BOOL;     (* Rising edge latch reset & alarm acknowledge pulse [BOOL] *)
    bManualOverride             : BOOL;     (* Force manual open-loop output commands [BOOL] *)

    (* Deep Cold Seawater Intake Measurements (TMR 2oo3) *)
    rT_ColdWater_Inlet_ChA      : REAL;     (* Deep cold seawater inlet temperature Channel A [deg C] *)
    rT_ColdWater_Inlet_ChB      : REAL;     (* Deep cold seawater inlet temperature Channel B [deg C] *)
    rT_ColdWater_Inlet_ChC      : REAL;     (* Deep cold seawater inlet temperature Channel C [deg C] *)
    rFlow_ColdWater_Actual      : REAL;     (* Volumetric flow rate cold deep seawater upwelling [m3/s] *)
    rDP_ColdWater_Riser         : REAL;     (* Deep seawater riser conduit differential pressure [bar] *)

    (* Surface Warm Seawater Measurements *)
    rT_WarmWater_Inlet          : REAL;     (* Surface warm seawater inlet temperature [deg C] *)
    rFlow_WarmWater_Actual      : REAL;     (* Volumetric flow rate surface warm seawater [m3/s] *)
    rHead_WarmWater_Pump        : REAL;     (* Warm seawater booster pump discharge head [bar] *)

    (* Working Fluid (Pure Anhydrous Ammonia R-717) Condenser Process Measurements *)
    rPress_Condenser_Shell      : REAL;     (* Condenser vapor dome absolute saturation pressure [bar] *)
    rT_Condensate_Liquid        : REAL;     (* Liquid condensate sump bulk temperature [deg C] *)
    rLevel_Condenser_Hotwell    : REAL;     (* Condenser hotwell liquid inventory level [0.0 to 100.0 %] *)
    rFlow_WorkingFluid_Feed     : REAL;     (* Working fluid cycle circulation mass flow rate [ton/h] *)

    (* Engineering Setpoints and Reference Targets *)
    rSP_SubCooling_Target       : REAL;     (* Target working fluid liquid sub-cooling margin [deg C] *)
    rSP_Hotwell_Level_Target    : REAL;     (* Target condensate hotwell inventory level [0.0 to 100.0 %] *)
    rRatio_Hydraulic_Target     : REAL;     (* Volumetric flow balance ratio (Warm/Cold) setpoint [-] *)
    rMaxAllowed_Riser_DP        : REAL;     (* Deep riser conduit maximum cavitation threshold [bar] *)
END_VAR

VAR_OUTPUT
    (* Operational Status Words and Diagnostic Latches *)
    bSystemReady                : BOOL;     (* System primed, interlocked, ready for full turbine load *)
    bTrip_Lockout               : BOOL;     (* Master safety trip lockout latch (requires bResetFaults) *)
    wSystemStatusWord           : WORD;     (* Status Word: B0:Run, B1:Ready, B2:DegradedTMR, B3:CavMit, B4:HydBal *)
    dwAlarmWord                 : DWORD;    (* Alarm Bitmask: B0:EStop, B1:HiP, B2:LoSubC, B3:RiserCav, B4:TMR_Err *)

    (* Actuator Command Demands (Continuous Scaled Outputs) *)
    rCmd_ColdWater_Pump_VFD     : REAL;     (* Cold seawater intake VFD speed command [0.0 to 100.0 %] *)
    rCmd_WarmWater_Pump_VFD     : REAL;     (* Warm seawater intake VFD speed command [0.0 to 100.0 %] *)
    rCmd_Condensate_Recirc_Vlv  : REAL;     (* Condensate sub-cooling trim / hotwell bypass valve [0.0 to 100.0 %] *)

    (* Online Thermodynamic & Process KPI Computations *)
    rCalc_T_Saturation          : REAL;     (* Working fluid saturation temperature at dome pressure [deg C] *)
    rCalc_SubCooling_Actual     : REAL;     (* Calculated online condensate sub-cooling margin [deg C] *)
    rCalc_Condenser_Duty_MWth   : REAL;     (* Calculated condenser thermal rejection duty [MWth] *)
    rHydraulic_Balance_Ratio    : REAL;     (* Actual volumetric flow balance ratio (Warm/Cold) [-] *)
    rVoted_ColdWater_Temp       : REAL;     (* Qualified 2oo3 cold seawater temperature [deg C] *)
END_VAR

VAR
    (* Execution Cycle Timing Constants *)
    rTs_Sec                     : REAL := 0.100;    (* Discrete sample time interval: 100 milliseconds [s] *)
    rAlpha_Filter               : REAL := 0.200;    (* Single-pole low-pass exponential filter constant *)

    (* Finite State Machine Control Registers *)
    iState                      : INT := 0;         (* Current operational execution state *)
    iPrevState                  : INT := 0;         (* Previous operational execution state *)
    tStateTimer                 : TON;              (* Dwell timer within current machine state *)

    (* Triple Modular Redundancy (2oo3) Voting & Qualification Architecture *)
    bChA_Valid                  : BOOL;             (* Health status of Channel A sensor *)
    bChB_Valid                  : BOOL;             (* Health status of Channel B sensor *)
    bChC_Valid                  : BOOL;             (* Health status of Channel C sensor *)
    rDiff_AB                    : REAL;             (* Absolute discrepancy: |ChA - ChB| *)
    rDiff_BC                    : REAL;             (* Absolute discrepancy: |ChB - ChC| *)
    rDiff_CA                    : REAL;             (* Absolute discrepancy: |ChC - ChA| *)
    rTMR_Tolerance_degC         : REAL := 1.20;     (* Permissible inter-channel deviation threshold [deg C] *)
    iDegradedChannelCount       : INT := 0;         (* Count of currently faulted TMR sensor channels *)

    (* First-Order Filter Accumulators *)
    rFilt_ColdFlow              : REAL := 0.0;      (* Filtered cold seawater volumetric flow [m3/s] *)
    rFilt_WarmFlow              : REAL := 0.0;      (* Filtered warm seawater volumetric flow [m3/s] *)
    rFilt_PressShell            : REAL := 6.50;     (* Filtered condenser shell pressure [bar] *)
    rFilt_RiserDP               : REAL := 0.0;      (* Filtered riser differential pressure [bar] *)

    (* Discrete 4x4 State-Space Model Predictive Control (MPC) Observer & Regulator *)
    (* State Vector: x[0]=SubCoolingErr, x[1]=LevelErr, x[2]=ColdFlowErr, x[3]=HydraulicRatioErr *)
    rState_x0_SubCoolErr        : REAL := 0.0;
    rState_x1_LevelErr          : REAL := 0.0;
    rState_x2_ColdFlowErr       : REAL := 0.0;
    rState_x3_RatioErr          : REAL := 0.0;

    (* Luenberger State Observer Estimated States *)
    rObs_x0                     : REAL := 0.0;
    rObs_x1                     : REAL := 0.0;
    rObs_x2                     : REAL := 0.0;
    rObs_x3                     : REAL := 0.0;

    (* System Dynamics Transition Matrix A (4x4) at Ts = 0.1s *)
    rA_00 : REAL := 0.8850;  rA_01 : REAL := 0.0020;  rA_02 : REAL :=-0.0450;  rA_03 : REAL := 0.0000;
    rA_10 : REAL := 0.0000;  rA_11 : REAL := 0.9650;  rA_12 : REAL := 0.0000;  rA_13 : REAL := 0.0000;
    rA_20 : REAL := 0.0000;  rA_21 : REAL := 0.0000;  rA_22 : REAL := 0.9120;  rA_23 : REAL := 0.0000;
    rA_30 : REAL := 0.0000;  rA_31 : REAL := 0.0000;  rA_32 : REAL :=-0.0820;  rA_33 : REAL := 0.8900;

    (* Input Coupling Matrix B (4x3) *)
    rB_00 : REAL := 0.0380;  rB_01 : REAL :=-0.0040;  rB_02 : REAL := 0.0620;
    rB_10 : REAL := 0.0000;  rB_11 : REAL := 0.0000;  rB_12 : REAL :=-0.0480;
    rB_20 : REAL := 0.0750;  rB_21 : REAL := 0.0000;  rB_22 : REAL := 0.0000;
    rB_30 : REAL :=-0.0320;  rB_31 : REAL := 0.0460;  rB_32 : REAL := 0.0000;

    (* Optimal LQR/MPC State Feedback Gain Matrix K (3x4) *)
    rK_00 : REAL := 1.8500;  rK_01 : REAL := 0.0420;  rK_02 : REAL := 0.7200;  rK_03 : REAL :=-0.3100;
    rK_10 : REAL :=-0.2400;  rK_11 : REAL := 0.0150;  rK_12 : REAL := 0.1500;  rK_13 : REAL := 1.4500;
    rK_20 : REAL := 2.6500;  rK_21 : REAL :=-1.8200;  rK_22 : REAL :=-0.1200;  rK_23 : REAL := 0.0000;

    (* Observer Innovation Gain Vector L (4x1) for Subcooling Feedback *)
    rL_Gain0                    : REAL := 0.2800;
    rL_Gain1                    : REAL := 0.0950;
    rL_Gain2                    : REAL := 0.1850;
    rL_Gain3                    : REAL := 0.1200;

    (* Controller Delta Increments & Integral Tracking Registers *)
    rDelta_U0_ColdPump          : REAL := 0.0;
    rDelta_U1_WarmPump          : REAL := 0.0;
    rDelta_U2_RecircVlv         : REAL := 0.0;
    rInt_ColdPump_Cmd           : REAL := 0.0;
    rInt_WarmPump_Cmd           : REAL := 0.0;
    rInt_RecircVlv_Cmd          : REAL := 0.0;

    (* Slew Rate Limiters (Water Hammer Protection in 1000m Cold Water Pipe) *)
    rMaxSlew_ColdPump_PctPerSec : REAL := 0.85;     (* Maximum acceleration rate 0.85%/sec *)
    rMaxSlew_WarmPump_PctPerSec : REAL := 2.00;     (* Surface pump rate limit 2.0%/sec *)
    rMaxSlew_Recirc_PctPerSec   : REAL := 10.0;     (* Fast trim valve response 10.0%/sec *)

    (* Timers for Fault Detection & Process Degradation *)
    tTimer_CavitationPersist    : TON;
    tTimer_SubCoolingDeficit    : TON;
    tTimer_TMR_Mismatch         : TON;
    tTimer_PrimingTimeout       : TON;

    (* Internal Flags & Scratchpad Registers *)
    rP_Clamped                  : REAL;
    rColdFlow_SafeDiv           : REAL;
    rInnovation                 : REAL;
    rDeltaLimit_Cold            : REAL;
    rDeltaLimit_Warm            : REAL;
    rDeltaLimit_Recirc          : REAL;
END_VAR

(*
====================================================================================================
  SECTION 1: FAIL-SAFE INTERLOCK & SHUTDOWN TRIP EVALUATION (SIL-3 EXECUTIVE)
====================================================================================================
*)

(* Evaluate hardwired emergency stop contact *)
IF NOT bEmergencyStop THEN
    bTrip_Lockout := TRUE;
    dwAlarmWord.%X0 := TRUE; (* Alarm Bit 0: Emergency Stop Asserted *)
END_IF;

(* Latch reset logic requires de-asserted E-Stop, reset pulse, and safe process conditions *)
IF bResetFaults AND bEmergencyStop THEN
    IF (rPress_Condenser_Shell < 11.5) AND (rDP_ColdWater_Riser < rMaxAllowed_Riser_DP) THEN
        bTrip_Lockout := FALSE;
        dwAlarmWord := 16#00000000;
    END_IF;
END_IF;

(* If trip is actively latched, enforce deterministic safe shutdown outputs *)
IF bTrip_Lockout THEN
    iState                  := 99; (* STATE_SAFETY_TRIP_LOCKOUT *)
    bSystemReady            := FALSE;
    rCmd_ColdWater_Pump_VFD := 0.0;
    rCmd_WarmWater_Pump_VFD := 0.0;
    rCmd_Condensate_Recirc_Vlv := 100.0; (* Full open bypass to protect condensate feed pumps *)
    wSystemStatusWord       := 16#0000;
    wSystemStatusWord.%X0   := FALSE;
    wSystemStatusWord.%X1   := FALSE;
    RETURN;
END_IF;

(*
====================================================================================================
  SECTION 2: TRIPLE MODULAR REDUNDANT (2oo3) TEMPERATURE QUALIFICATION
====================================================================================================
*)

(* Calculate inter-channel discrepancies *)
rDiff_AB := ABS(rT_ColdWater_Inlet_ChA - rT_ColdWater_Inlet_ChB);
rDiff_BC := ABS(rT_ColdWater_Inlet_ChB - rT_ColdWater_Inlet_ChC);
rDiff_CA := ABS(rT_ColdWater_Inlet_ChC - rT_ColdWater_Inlet_ChA);

(* Individual sensor sanity range verification [1.0 deg C to 18.0 deg C] *)
bChA_Valid := (rT_ColdWater_Inlet_ChA >= 1.0) AND (rT_ColdWater_Inlet_ChA <= 18.0);
bChB_Valid := (rT_ColdWater_Inlet_ChB >= 1.0) AND (rT_ColdWater_Inlet_ChB <= 18.0);
bChC_Valid := (rT_ColdWater_Inlet_ChC >= 1.0) AND (rT_ColdWater_Inlet_ChC <= 18.0);

(* 2oo3 Voting & Fault Isolation Algorithm *)
IF bChA_Valid AND bChB_Valid AND bChC_Valid THEN
    IF (rDiff_AB <= rTMR_Tolerance_degC) AND (rDiff_BC <= rTMR_Tolerance_degC) AND (rDiff_CA <= rTMR_Tolerance_degC) THEN
        (* All three channels concordant: Exact median selection *)
        IF (rT_ColdWater_Inlet_ChA >= rT_ColdWater_Inlet_ChB) THEN
            IF (rT_ColdWater_Inlet_ChB >= rT_ColdWater_Inlet_ChC) THEN
                rVoted_ColdWater_Temp := rT_ColdWater_Inlet_ChB;
            ELSIF (rT_ColdWater_Inlet_ChA <= rT_ColdWater_Inlet_ChC) THEN
                rVoted_ColdWater_Temp := rT_ColdWater_Inlet_ChA;
            ELSE
                rVoted_ColdWater_Temp := rT_ColdWater_Inlet_ChC;
            END_IF;
        ELSE
            IF (rT_ColdWater_Inlet_ChA >= rT_ColdWater_Inlet_ChC) THEN
                rVoted_ColdWater_Temp := rT_ColdWater_Inlet_ChA;
            ELSIF (rT_ColdWater_Inlet_ChB <= rT_ColdWater_Inlet_ChC) THEN
                rVoted_ColdWater_Temp := rT_ColdWater_Inlet_ChB;
            ELSE
                rVoted_ColdWater_Temp := rT_ColdWater_Inlet_ChC;
            END_IF;
        END_IF;
        iDegradedChannelCount := 0;
        wSystemStatusWord.%X2 := FALSE; (* Degraded flag cleared *)
    ELSIF (rDiff_AB <= rTMR_Tolerance_degC) THEN
        (* Channel C divergent: Isolate Channel C, average ChA & ChB *)
        rVoted_ColdWater_Temp := (rT_ColdWater_Inlet_ChA + rT_ColdWater_Inlet_ChB) * 0.5;
        iDegradedChannelCount := 1;
        wSystemStatusWord.%X2 := TRUE; (* Degraded TMR flag *)
        dwAlarmWord.%X4       := TRUE; (* Sensor Discrepancy Alarm *)
    ELSIF (rDiff_BC <= rTMR_Tolerance_degC) THEN
        (* Channel A divergent: Isolate Channel A, average ChB & ChC *)
        rVoted_ColdWater_Temp := (rT_ColdWater_Inlet_ChB + rT_ColdWater_Inlet_ChC) * 0.5;
        iDegradedChannelCount := 1;
        wSystemStatusWord.%X2 := TRUE;
        dwAlarmWord.%X4       := TRUE;
    ELSIF (rDiff_CA <= rTMR_Tolerance_degC) THEN
        (* Channel B divergent: Isolate Channel B, average ChA & ChC *)
        rVoted_ColdWater_Temp := (rT_ColdWater_Inlet_ChA + rT_ColdWater_Inlet_ChC) * 0.5;
        iDegradedChannelCount := 1;
        wSystemStatusWord.%X2 := TRUE;
        dwAlarmWord.%X4       := TRUE;
    ELSE
        (* All three sensors mutually divergent - Fail-Safe Fallback to Maximum Cold Temp *)
        rVoted_ColdWater_Temp := MAX(rT_ColdWater_Inlet_ChA, MAX(rT_ColdWater_Inlet_ChB, rT_ColdWater_Inlet_ChC));
        iDegradedChannelCount := 3;
        wSystemStatusWord.%X2 := TRUE;
        dwAlarmWord.%X4       := TRUE;
    END_IF;
ELSE
    (* Sensor out-of-range fallback *)
    IF bChA_Valid AND bChB_Valid THEN
        rVoted_ColdWater_Temp := (rT_ColdWater_Inlet_ChA + rT_ColdWater_Inlet_ChB) * 0.5;
        iDegradedChannelCount := 1;
    ELSIF bChB_Valid AND bChC_Valid THEN
        rVoted_ColdWater_Temp := (rT_ColdWater_Inlet_ChB + rT_ColdWater_Inlet_ChC) * 0.5;
        iDegradedChannelCount := 1;
    ELSIF bChA_Valid AND bChC_Valid THEN
        rVoted_ColdWater_Temp := (rT_ColdWater_Inlet_ChA + rT_ColdWater_Inlet_ChC) * 0.5;
        iDegradedChannelCount := 1;
    ELSIF bChA_Valid THEN
        rVoted_ColdWater_Temp := rT_ColdWater_Inlet_ChA;
        iDegradedChannelCount := 2;
    ELSIF bChB_Valid THEN
        rVoted_ColdWater_Temp := rT_ColdWater_Inlet_ChB;
        iDegradedChannelCount := 2;
    ELSIF bChC_Valid THEN
        rVoted_ColdWater_Temp := rT_ColdWater_Inlet_ChC;
        iDegradedChannelCount := 2;
    ELSE
        (* Complete sensor bank failure: Trip immediately *)
        bTrip_Lockout := TRUE;
        dwAlarmWord.%X4 := TRUE;
        RETURN;
    END_IF;
    wSystemStatusWord.%X2 := TRUE;
END_IF;

(*
====================================================================================================
  SECTION 3: SIGNAL FILTERING & THERMODYNAMIC STATE CALCULATIONS
====================================================================================================
*)

(* Low-pass filter raw analog inputs *)
rFilt_ColdFlow   := (rAlpha_Filter * rFlow_ColdWater_Actual) + ((1.0 - rAlpha_Filter) * rFilt_ColdFlow);
rFilt_WarmFlow   := (rAlpha_Filter * rFlow_WarmWater_Actual) + ((1.0 - rAlpha_Filter) * rFilt_WarmFlow);
rFilt_PressShell := (rAlpha_Filter * rPress_Condenser_Shell) + ((1.0 - rAlpha_Filter) * rFilt_PressShell);
rFilt_RiserDP    := (rAlpha_Filter * rDP_ColdWater_Riser)    + ((1.0 - rAlpha_Filter) * rFilt_RiserDP);

(* High-precision 4th-order polynomial for Anhydrous Ammonia (R-717) Saturation Temperature *)
(* Pressure range: 4.0 bar to 12.0 bar absolute *)
rP_Clamped := LIMIT(4.0, rFilt_PressShell, 14.0);
rCalc_T_Saturation := -29.620 
                      + (7.7410 * rP_Clamped) 
                      - (0.3342 * rP_Clamped * rP_Clamped) 
                      + (0.00762 * rP_Clamped * rP_Clamped * rP_Clamped);

(* Sub-cooling Margin: Difference between saturation temperature and bulk condensate *)
rCalc_SubCooling_Actual := rCalc_T_Saturation - rT_Condensate_Liquid;

(* Hydraulic Warm/Cold Flow Balance Ratio *)
rColdFlow_SafeDiv := MAX(rFilt_ColdFlow, 0.05);
rHydraulic_Balance_Ratio := rFilt_WarmFlow / rColdFlow_SafeDiv;

(* Thermal Rejection Duty: Q = mass_flow_CW * Cp_seawater * DeltaT_CW (MWth) *)
(* Seawater Density = 1025 kg/m3, Specific Heat Cp = 3.99 kJ/(kg*K) *)
rCalc_Condenser_Duty_MWth := (rFilt_ColdFlow * 1025.0 * 3.99 * (rCalc_T_Saturation - rVoted_ColdWater_Temp - rCalc_SubCooling_Actual)) / 1000.0;
rCalc_Condenser_Duty_MWth := MAX(rCalc_Condenser_Duty_MWth, 0.0);

(*
====================================================================================================
  SECTION 4: COMPREHENSIVE PROCESS ALARM MONITORING TREE
====================================================================================================
*)

(* Alarm 1: High Condenser Shell Pressure Trip Threshold *)
IF (rFilt_PressShell >= 10.8) THEN
    dwAlarmWord.%X1 := TRUE;
    bTrip_Lockout   := TRUE; (* Instantaneous over-pressure safety trip *)
ELSIF (rFilt_PressShell < 9.8) THEN
    dwAlarmWord.%X1 := FALSE;
END_IF;

(* Alarm 2: Sub-Cooling Deficit Timer (Risk of condensate feed pump cavitation) *)
tTimer_SubCoolingDeficit(IN := (rCalc_SubCooling_Actual < 0.65) AND (iState >= 30), PT := T#3S);
IF tTimer_SubCoolingDeficit.Q THEN
    dwAlarmWord.%X2 := TRUE; (* Alarm Bit 2: Low Sub-Cooling Hazard *)
ELSIF (rCalc_SubCooling_Actual >= 1.20) THEN
    dwAlarmWord.%X2 := FALSE;
END_IF;

(* Alarm 3: Deep Riser Cavitation & Water-Hammer Risk (Excessive Differential Pressure) *)
tTimer_CavitationPersist(IN := (rFilt_RiserDP >= rMaxAllowed_Riser_DP) AND (iState >= 20), PT := T#2S);
IF tTimer_CavitationPersist.Q THEN
    dwAlarmWord.%X3 := TRUE; (* Alarm Bit 3: Riser Cavitation / Friction Choke *)
ELSIF (rFilt_RiserDP < (rMaxAllowed_Riser_DP * 0.85)) THEN
    dwAlarmWord.%X3 := FALSE;
END_IF;

(* Alarm 5: Hotwell Level Critical Limits *)
IF (rLevel_Condenser_Hotwell < 15.0) THEN
    dwAlarmWord.%X5 := TRUE; (* Alarm Bit 5: Hotwell Low-Low Level Trip *)
    bTrip_Lockout   := TRUE;
ELSIF (rLevel_Condenser_Hotwell > 25.0) THEN
    dwAlarmWord.%X5 := FALSE;
END_IF;

IF (rLevel_Condenser_Hotwell > 92.0) THEN
    dwAlarmWord.%X6 := TRUE; (* Alarm Bit 6: Hotwell High-High Level Warning *)
ELSIF (rLevel_Condenser_Hotwell < 85.0) THEN
    dwAlarmWord.%X6 := FALSE;
END_IF;

(* Alarm 7: Hydraulic Flow Imbalance Warning *)
IF (ABS(rHydraulic_Balance_Ratio - rRatio_Hydraulic_Target) > 0.40) AND (iState >= 30) THEN
    dwAlarmWord.%X7 := TRUE; (* Alarm Bit 7: Severe Hydraulic Imbalance *)
ELSE
    dwAlarmWord.%X7 := FALSE;
END_IF;

(*
====================================================================================================
  SECTION 5: MULTI-STAGE COGNITIVE FINITE STATE MACHINE (ISA-88 ALIGNED)
====================================================================================================
*)

(* State Dwell Time Accumulator *)
tStateTimer(IN := (iState = iPrevState), PT := T#24H);
IF (iState <> iPrevState) THEN
    iPrevState := iState;
    tStateTimer(IN := FALSE);
END_IF;

CASE iState OF

    0: (* STATE_IDLE_STANDBY: All pumps quiescent, siphon lines sealed *)
        bSystemReady            := FALSE;
        rInt_ColdPump_Cmd       := 0.0;
        rInt_WarmPump_Cmd       := 0.0;
        rInt_RecircVlv_Cmd      := 50.0;
        wSystemStatusWord.%X0   := FALSE;
        wSystemStatusWord.%X1   := FALSE;

        IF bEnable AND (NOT bTrip_Lockout) THEN
            iState := 10; (* Transition to Siphon Priming *)
        END_IF;

    10: (* STATE_SIPHON_PRIMING: Vacuum degassing and intake column priming *)
        bSystemReady            := FALSE;
        rInt_ColdPump_Cmd       := 5.0;  (* Minimum trickle purge velocity *)
        rInt_WarmPump_Cmd       := 10.0; (* Flush surface loop *)
        rInt_RecircVlv_Cmd      := 75.0; (* Maintain loop circulation *)

        tTimer_PrimingTimeout(IN := TRUE, PT := T#45S);
        IF (tTimer_PrimingTimeout.Q) AND (rFilt_ColdFlow >= 0.15) AND (rFilt_WarmFlow >= 0.30) THEN
            tTimer_PrimingTimeout(IN := FALSE);
            iState := 20; (* Transition to Controlled Soft Ramp *)
        ELSIF tTimer_PrimingTimeout.Q THEN
            tTimer_PrimingTimeout(IN := FALSE);
            bTrip_Lockout := TRUE; (* Priming failure abort *)
        END_IF;

    20: (* STATE_CONTROLLED_SOFT_RAMP: Progressive upwelling without acoustic water hammer *)
        bSystemReady := FALSE;
        wSystemStatusWord.%X0 := TRUE; (* Running *)

        (* Ramp Cold Pump speed smoothly toward baseline operating point (60%) *)
        IF (rInt_ColdPump_Cmd < 60.0) THEN
            rInt_ColdPump_Cmd := rInt_ColdPump_Cmd + (rMaxSlew_ColdPump_PctPerSec * rTs_Sec);
        END_IF;

        (* Coordinate Warm Pump to track hydraulic ratio setpoint *)
        IF (rInt_WarmPump_Cmd < (rInt_ColdPump_Cmd * rRatio_Hydraulic_Target)) THEN
            rInt_WarmPump_Cmd := rInt_WarmPump_Cmd + (rMaxSlew_WarmPump_PctPerSec * rTs_Sec);
        END_IF;

        (* Check transition conditions to active closed-loop regulation *)
        IF (rInt_ColdPump_Cmd >= 58.0) AND (rCalc_SubCooling_Actual >= (rSP_SubCooling_Target * 0.75)) THEN
            iState := 30; (* Enter Multivariable Model Predictive Normal State *)
        END_IF;

        IF dwAlarmWord.%X3 THEN
            iState := 50; (* Divert to Cavitation Mitigation immediately *)
        END_IF;

    30: (* STATE_AUTO_MPC_NORMAL: Multivariable state-space balance and sub-cooling control *)
        bSystemReady            := TRUE;
        wSystemStatusWord.%X0   := TRUE;
        wSystemStatusWord.%X1   := TRUE;
        wSystemStatusWord.%X3   := FALSE;

        (* Compute normalized control error states *)
        rState_x0_SubCoolErr    := rSP_SubCooling_Target - rCalc_SubCooling_Actual;
        rState_x1_LevelErr      := rSP_Hotwell_Level_Target - rLevel_Condenser_Hotwell;
        rState_x2_ColdFlowErr   := (rFlow_WorkingFluid_Feed * 0.08) - rFilt_ColdFlow;
        rState_x3_RatioErr      := rRatio_Hydraulic_Target - rHydraulic_Balance_Ratio;

        (* Luenberger State Observer Update with Innovation Gain *)
        rInnovation := rState_x0_SubCoolErr - rObs_x0;
        rObs_x0 := (rA_00 * rObs_x0) + (rA_01 * rObs_x1) + (rA_02 * rObs_x2) + (rA_03 * rObs_x3) 
                   + (rB_00 * rDelta_U0_ColdPump) + (rB_01 * rDelta_U1_WarmPump) + (rB_02 * rDelta_U2_RecircVlv) 
                   + (rL_Gain0 * rInnovation);

        rObs_x1 := (rA_10 * rObs_x0) + (rA_11 * rObs_x1) + (rA_12 * rObs_x2) + (rA_13 * rObs_x3) 
                   + (rB_10 * rDelta_U0_ColdPump) + (rB_11 * rDelta_U1_WarmPump) + (rB_12 * rDelta_U2_RecircVlv) 
                   + (rL_Gain1 * rInnovation);

        rObs_x2 := (rA_20 * rObs_x0) + (rA_21 * rObs_x1) + (rA_22 * rObs_x2) + (rA_23 * rObs_x3) 
                   + (rB_20 * rDelta_U0_ColdPump) + (rB_21 * rDelta_U1_WarmPump) + (rB_22 * rDelta_U2_RecircVlv) 
                   + (rL_Gain2 * rInnovation);

        rObs_x3 := (rA_30 * rObs_x0) + (rA_31 * rObs_x1) + (rA_32 * rObs_x2) + (rA_33 * rObs_x3) 
                   + (rB_30 * rDelta_U0_ColdPump) + (rB_31 * rDelta_U1_WarmPump) + (rB_32 * rDelta_U2_RecircVlv) 
                   + (rL_Gain3 * rInnovation);

        (* MPC Optimal State Feedback Incremental Law: Delta_U = -K * x_hat *)
        rDelta_U0_ColdPump := - ((rK_00 * rObs_x0) + (rK_01 * rObs_x1) + (rK_02 * rObs_x2) + (rK_03 * rObs_x3));
        rDelta_U1_WarmPump := - ((rK_10 * rObs_x0) + (rK_11 * rObs_x1) + (rK_12 * rObs_x2) + (rK_13 * rObs_x3));
        rDelta_U2_RecircVlv:= - ((rK_20 * rObs_x0) + (rK_21 * rObs_x1) + (rK_22 * rObs_x2) + (rK_23 * rObs_x3));

        (* Integrate control increments with integral tracking *)
        rInt_ColdPump_Cmd  := rInt_ColdPump_Cmd  + (rDelta_U0_ColdPump  * rTs_Sec);
        rInt_WarmPump_Cmd  := rInt_WarmPump_Cmd  + (rDelta_U1_WarmPump  * rTs_Sec);
        rInt_RecircVlv_Cmd := rInt_RecircVlv_Cmd + (rDelta_U2_RecircVlv * rTs_Sec);

        (* Transition to Cavitation Mitigation if conduit differential pressure trips *)
        IF dwAlarmWord.%X3 THEN
            iState := 50;
        END_IF;

        (* Check for degraded sensor status *)
        IF (iDegradedChannelCount > 0) THEN
            iState := 40; (* Shift to Degraded Mode *)
        END_IF;

        IF NOT bEnable THEN
            iState := 80; (* Transition to Controlled Cooldown *)
        END_IF;

    40: (* STATE_DEGRADED_TMR_FALLBACK: Sensor loss tolerance mode with safety de-rating *)
        wSystemStatusWord.%X2 := TRUE; (* Degraded flag *)

        (* Widen safety margin: enforce higher subcooling setpoint to prevent cavitation *)
        IF (rCalc_SubCooling_Actual < (rSP_SubCooling_Target + 0.50)) THEN
            rInt_ColdPump_Cmd := rInt_ColdPump_Cmd + (0.5 * rTs_Sec);
            rInt_RecircVlv_Cmd := rInt_RecircVlv_Cmd + (2.0 * rTs_Sec);
        END_IF;

        (* Maintain hydraulic ratio conservative lock *)
        rInt_WarmPump_Cmd := rInt_ColdPump_Cmd * rRatio_Hydraulic_Target;

        (* Return to normal state if sensor health recovered *)
        IF (iDegradedChannelCount = 0) THEN
            iState := 30;
        END_IF;

        IF dwAlarmWord.%X3 THEN
            iState := 50;
        END_IF;

        IF NOT bEnable THEN
            iState := 80;
        END_IF;

    50: (* STATE_RISER_CAVITATION_MITIGATION: Urgent dynamic throttling of intake upwelling *)
        wSystemStatusWord.%X3 := TRUE; (* Cavitation Mitigation Active *)
        bSystemReady          := FALSE;

        (* Rapidly shed Cold Pump load to drop suction head loss (without inducing negative hammer) *)
        rInt_ColdPump_Cmd := rInt_ColdPump_Cmd - (rMaxSlew_ColdPump_PctPerSec * 1.5 * rTs_Sec);
        rInt_ColdPump_Cmd := MAX(rInt_ColdPump_Cmd, 35.0); (* Enforce floor to avoid siphon collapse *)

        (* Open condensate recirc to maintain subcooling despite reduced cold seawater *)
        rInt_RecircVlv_Cmd := rInt_RecircVlv_Cmd + (rMaxSlew_Recirc_PctPerSec * 0.5 * rTs_Sec);

        (* Throttle warm pump to maintain volumetric balance *)
        rInt_WarmPump_Cmd := rInt_ColdPump_Cmd * rRatio_Hydraulic_Target;

        (* When differential pressure normalizes below 80% threshold for > 5 sec, return to ramp *)
        IF (rFilt_RiserDP < (rMaxAllowed_Riser_DP * 0.80)) AND (tStateTimer.ET >= T#5S) THEN
            wSystemStatusWord.%X3 := FALSE;
            iState := 20; (* Return to Controlled Ramp *)
        END_IF;

    80: (* STATE_CONTROLLED_STOP_DRAIN: Graceful shedding of flow velocities *)
        bSystemReady := FALSE;

        IF (rInt_ColdPump_Cmd > 5.0) THEN
            rInt_ColdPump_Cmd := rInt_ColdPump_Cmd - (rMaxSlew_ColdPump_PctPerSec * rTs_Sec);
        ELSE
            rInt_ColdPump_Cmd := 0.0;
        END_IF;

        IF (rInt_WarmPump_Cmd > 5.0) THEN
            rInt_WarmPump_Cmd := rInt_WarmPump_Cmd - (rMaxSlew_WarmPump_PctPerSec * rTs_Sec);
        ELSE
            rInt_WarmPump_Cmd := 0.0;
        END_IF;

        rInt_RecircVlv_Cmd := 100.0; (* Fully recirculate working fluid to balance hotwell *)

        IF (rInt_ColdPump_Cmd <= 0.0) AND (rInt_WarmPump_Cmd <= 0.0) THEN
            iState := 0; (* Return to Standby *)
        END_IF;

    99: (* STATE_SAFETY_TRIP_LOCKOUT: Safe lock state *)
        bSystemReady            := FALSE;
        rInt_ColdPump_Cmd       := 0.0;
        rInt_WarmPump_Cmd       := 0.0;
        rInt_RecircVlv_Cmd      := 100.0;
        wSystemStatusWord       := 16#0000;

END_CASE;

(*
====================================================================================================
  SECTION 6: ACTUATOR SLEW-RATE LIMITING & SATURATION CLAMPING
====================================================================================================
*)

(* Enforce strict acceleration boundaries to protect massive marine hydraulic infrastructure *)
rDeltaLimit_Cold   := rMaxSlew_ColdPump_PctPerSec * rTs_Sec;
rDeltaLimit_Warm   := rMaxSlew_WarmPump_PctPerSec * rTs_Sec;
rDeltaLimit_Recirc := rMaxSlew_Recirc_PctPerSec   * rTs_Sec;

(* Slew limiter on Cold Seawater Pump command *)
IF (rInt_ColdPump_Cmd - rCmd_ColdWater_Pump_VFD) > rDeltaLimit_Cold THEN
    rCmd_ColdWater_Pump_VFD := rCmd_ColdWater_Pump_VFD + rDeltaLimit_Cold;
ELSIF (rCmd_ColdWater_Pump_VFD - rInt_ColdPump_Cmd) > rDeltaLimit_Cold THEN
    rCmd_ColdWater_Pump_VFD := rCmd_ColdWater_Pump_VFD - rDeltaLimit_Cold;
ELSE
    rCmd_ColdWater_Pump_VFD := rInt_ColdPump_Cmd;
END_IF;

(* Slew limiter on Warm Seawater Pump command *)
IF (rInt_WarmPump_Cmd - rCmd_WarmWater_Pump_VFD) > rDeltaLimit_Warm THEN
    rCmd_WarmWater_Pump_VFD := rCmd_WarmWater_Pump_VFD + rDeltaLimit_Warm;
ELSIF (rCmd_WarmWater_Pump_VFD - rInt_WarmPump_Cmd) > rDeltaLimit_Warm THEN
    rCmd_WarmWater_Pump_VFD := rCmd_WarmWater_Pump_VFD - rDeltaLimit_Warm;
ELSE
    rCmd_WarmWater_Pump_VFD := rInt_WarmPump_Cmd;
END_IF;

(* Slew limiter on Condensate Recirculation Trim Valve *)
IF (rInt_RecircVlv_Cmd - rCmd_Condensate_Recirc_Vlv) > rDeltaLimit_Recirc THEN
    rCmd_Condensate_Recirc_Vlv := rCmd_Condensate_Recirc_Vlv + rDeltaLimit_Recirc;
ELSIF (rCmd_Condensate_Recirc_Vlv - rInt_RecircVlv_Cmd) > rDeltaLimit_Recirc THEN
    rCmd_Condensate_Recirc_Vlv := rCmd_Condensate_Recirc_Vlv - rDeltaLimit_Recirc;
ELSE
    rCmd_Condensate_Recirc_Vlv := rInt_RecircVlv_Cmd;
END_IF;

(* Clamp actuator signals to permissible mechanical range [0.0% to 100.0%] *)
rCmd_ColdWater_Pump_VFD    := LIMIT(0.0, rCmd_ColdWater_Pump_VFD, 100.0);
rCmd_WarmWater_Pump_VFD    := LIMIT(0.0, rCmd_WarmWater_Pump_VFD, 100.0);
rCmd_Condensate_Recirc_Vlv := LIMIT(0.0, rCmd_Condensate_Recirc_Vlv, 100.0);

(* Pack final Status Word bits *)
wSystemStatusWord.%X4 := (ABS(rHydraulic_Balance_Ratio - rRatio_Hydraulic_Target) <= 0.15); (* Hydraulic Balanced *)
wSystemStatusWord.%X5 := (rCalc_SubCooling_Actual >= rSP_SubCooling_Target);                 (* Subcooling Optimal *)

END_FUNCTION_BLOCK
